import json
from pathlib import Path
p=Path('/Users/oubiwann/Library/Application Support/ChatGPT-Profiles/personal/codex-home/sessions/2026/11/21/rollout-2026-11-21T17-25-49-01a2006e-2618-7721-b361-1bd809d21d87.jsonl')
latest=None
try:
    for line in p.open():
        try: row=json.loads(line)
        except json.JSONDecodeError: continue
        def find(obj):
            if isinstance(obj, dict):
                if obj.get('type') == 'turn_context':
                    return obj
                for value in obj.values():
                    got=find(value)
                    if got is not None: return got
            elif isinstance(obj, list):
                for value in obj:
                    got=find(value)
                    if got is not None: return got
            return None
        tc=find(row)
        if tc is not None: latest=tc
    if latest is None:
        print('turn_context: not found in readable own-session JSONL')
    else:
        def pick(obj, names):
            if isinstance(obj, dict):
                out={k:obj[k] for k in names if k in obj}
                if out: return out
                for v in obj.values():
                    got=pick(v,names)
                    if got: return got
            elif isinstance(obj,list):
                for v in obj:
                    got=pick(v,names)
                    if got: return got
            return {}
        wanted=pick(latest, ['model','effort','cwd','approval_policy','sandbox_policy'])
        print(json.dumps(wanted,sort_keys=True))
except OSError as e:
    print(f'turn_context: own-session access unavailable ({type(e).__name__})')
