/opt/homebrew/bin/bash -lc "python3 - <<'PY'
import subprocess,tomllib,json
paths=subprocess.check_output(['git','ls-files','Cargo.toml','crates/**/Cargo.toml'],text=True).splitlines()
parsed={}
for p in paths:
 with open(p,'rb') as f: parsed[p]=tomllib.load(f)
for p in paths[1:22]:
 d=parsed[p]; pkg=d.get('package',{}).get('name','<virtual>'); parts=[]
 for sec in ('dependencies','dev-dependencies','build-dependencies'):
  for n,v in d.get(sec,{}).items():
   if isinstance(v,str): v={'version':v}
   spec=[]
   for k in ('workspace','version','path','git'):
    if k in v:spec.append(f'{k}={v[k]}')
   for k in ('features','default-features','optional'):
    if k in v:spec.append(f'{k}={v[k]}')
   parts.append(f'{sec}:{n}['+','.join(spec)+']')
 for tgt,tables in d.get('target',{}).items():
  for sec in ('dependencies','dev-dependencies','build-dependencies'):
   for n,v in tables.get(sec,{}).items():
    if isinstance(v,str):v={'version':v}
    spec=[]
    for k in ('workspace','version','path','git','features','default-features','optional'):
     if k in v:spec.append(f'{k}={v[k]}')
    parts.append(f'target.{tgt}.{sec}:{n}['+','.join(spec)+']')
 print(json.dumps({'manifest':p,'package':pkg,'decls':parts,'features':d.get('features',{})},separators=(',',':')))
PY"

