//! Search document representation.
//!
//! This module defines `SearchDocument`, the struct used to represent indexed
//! content. It maps directly to the schema fields defined in `schema.rs`.
//!
//! # Creating Documents
//!
//! Documents can be created from domain-specific metadata types using the
//! builder pattern or direct construction:
//!
//! ```rust
//! use fabryk_fts::SearchDocument;
//!
//! let doc = SearchDocument::builder()
//!     .id("my-concept")
//!     .title("My Concept")
//!     .content("The main content...")
//!     .category("fundamentals")
//!     .build();
//! ```
//!
//! # Relevance Scoring
//!
//! The document provides a `matches_query()` method for simple substring
//! matching and a `relevance()` method for weighted scoring (used by
//! `SimpleSearch`).

use serde::{Deserialize, Serialize};

/// A document to be indexed and searched.
///
/// This struct holds all fields that can be indexed and searched.
/// It maps to the default schema defined in `schema.rs`.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct SearchDocument {
    // Identity
    /// Unique document identifier (required).
    pub id: String,
    /// File path for reference.
    pub path: String,

    // Full-text fields
    /// Document title (required, boosted 3.0x in search).
    pub title: String,
    /// Brief description (boosted 2.0x in search).
    pub description: Option<String>,
    /// Main content body (boosted 1.0x in search).
    pub content: String,

    // Facet fields
    /// Content category (e.g., "harmony", "rhythm").
    pub category: String,
    /// Source reference (e.g., "Open Music Theory").
    pub source: Option<String>,
    /// Tags for additional categorization.
    pub tags: Vec<String>,

    // Metadata fields
    /// Chapter reference.
    pub chapter: Option<String>,
    /// Part within source.
    pub part: Option<String>,
    /// Content author.
    pub author: Option<String>,
    /// Publication/creation date.
    pub date: Option<String>,
    /// Content type classification.
    pub content_type: Option<String>,
    /// Section reference.
    pub section: Option<String>,
}

impl SearchDocument {
    /// Create a new document builder.
    pub fn builder() -> SearchDocumentBuilder {
        SearchDocumentBuilder::default()
    }

    /// Check if the document matches a query (case-insensitive substring match).
    ///
    /// Searches in: title, description, content, category, source, tags.
    pub fn matches_query(&self, query: &str) -> bool {
        if query.is_empty() || query == "*" {
            return true;
        }

        let query_lower = query.to_lowercase();

        self.title.to_lowercase().contains(&query_lower)
            || self
                .description
                .as_ref()
                .map(|d| d.to_lowercase().contains(&query_lower))
                .unwrap_or(false)
            || self.content.to_lowercase().contains(&query_lower)
            || self.category.to_lowercase().contains(&query_lower)
            || self
                .source
                .as_ref()
                .map(|s| s.to_lowercase().contains(&query_lower))
                .unwrap_or(false)
            || self
                .tags
                .iter()
                .any(|t| t.to_lowercase().contains(&query_lower))
    }

    /// Calculate relevance score for a query.
    ///
    /// Uses weighted field matching:
    /// - Title match: 3.0
    /// - Description match: 2.0
    /// - Content match: 1.0
    /// - Category/source/tags: 0.5 each
    pub fn relevance(&self, query: &str) -> f32 {
        if query.is_empty() || query == "*" {
            return 1.0;
        }

        let query_lower = query.to_lowercase();
        let mut score = 0.0;

        if self.title.to_lowercase().contains(&query_lower) {
            score += 3.0;
        }

        if self
            .description
            .as_ref()
            .map(|d| d.to_lowercase().contains(&query_lower))
            .unwrap_or(false)
        {
            score += 2.0;
        }

        if self.content.to_lowercase().contains(&query_lower) {
            score += 1.0;
        }

        if self.category.to_lowercase().contains(&query_lower) {
            score += 0.5;
        }

        if self
            .source
            .as_ref()
            .map(|s| s.to_lowercase().contains(&query_lower))
            .unwrap_or(false)
        {
            score += 0.5;
        }

        if self
            .tags
            .iter()
            .any(|t| t.to_lowercase().contains(&query_lower))
        {
            score += 0.5;
        }

        score
    }

    /// Extract a snippet around the query match.
    ///
    /// Returns a portion of the content centered on the first match,
    /// with ellipsis if truncated.
    pub fn extract_snippet(&self, query: &str, max_length: usize) -> Option<String> {
        if query.is_empty() || query == "*" {
            return self.description.clone().or_else(|| {
                if self.content.len() > max_length {
                    let end = self.content.floor_char_boundary(max_length);
                    Some(format!("{}...", &self.content[..end]))
                } else {
                    Some(self.content.clone())
                }
            });
        }

        let query_lower = query.to_lowercase();
        })
    }

    /// Create an in-memory index (for testing).
    pub fn new_in_memory(schema: &SearchSchema) -> Result<Self> {
        let index = Index::create_in_ram(schema.schema().clone());
        SearchSchema::register_tokenizers(&index);

        let writer = index
            .writer(WRITER_BUFFER_SIZE)
            .map_err(|e| Error::operation(format!("Failed to create index writer: {e}")))?;

        Ok(Self {
            index,
            writer,
            schema: schema.clone(),
        })
    }

    /// Add a document to the index.
    ///
    /// The document is staged but not yet searchable until `commit()` is called.
    pub fn add_document(&mut self, doc: &SearchDocument) -> Result<()> {
        let tantivy_doc = self.convert_to_tantivy_doc(doc);
        self.writer
            .add_document(tantivy_doc)
            .map_err(|e| Error::operation(format!("Failed to add document: {e}")))?;
        Ok(())
    }

    /// Commit staged changes to make them searchable.
    pub fn commit(&mut self) -> Result<()> {
        self.writer
            .commit()
            .map_err(|e| Error::operation(format!("Failed to commit index: {e}")))?;
        Ok(())
    }

    /// Clear all documents from the index.
    pub fn clear(&mut self) -> Result<()> {
        self.writer
            .delete_all_documents()
            .map_err(|e| Error::operation(format!("Failed to clear index: {e}")))?;
        self.commit()
    }

    /// Get reference to the underlying Tantivy index.
    pub fn index(&self) -> &Index {
        &self.index
    }

    /// Get the schema.
    pub fn schema(&self) -> &SearchSchema {
        &self.schema
    }

    /// Convert SearchDocument to Tantivy document.
    fn convert_to_tantivy_doc(&self, doc: &SearchDocument) -> TantivyDocument {
        let s = &self.schema;

        let mut tantivy_doc = TantivyDocument::new();

        // Identity fields
        add_text(&mut tantivy_doc, s.id, &doc.id);
        add_text(&mut tantivy_doc, s.path, &doc.path);

        // Full-text fields
        add_text(&mut tantivy_doc, s.title, &doc.title);
        if let Some(ref desc) = doc.description {
            add_text(&mut tantivy_doc, s.description, desc);
        }
        add_text(&mut tantivy_doc, s.content, &doc.content);

        // Facet fields
        add_text(&mut tantivy_doc, s.category, &doc.category);
        if let Some(ref source) = doc.source {
            add_text(&mut tantivy_doc, s.source, source);
        }
        for tag in &doc.tags {
            add_text(&mut tantivy_doc, s.tags, tag);
        }

        // Metadata fields
        if let Some(ref chapter) = doc.chapter {
            add_text(&mut tantivy_doc, s.chapter, chapter);
        }
        if let Some(ref part) = doc.part {
            add_text(&mut tantivy_doc, s.part, part);
        }
        if let Some(ref author) = doc.author {
            add_text(&mut tantivy_doc, s.author, author);
        }
        if let Some(ref date) = doc.date {
            add_text(&mut tantivy_doc, s.date, date);
        }
        if let Some(ref content_type) = doc.content_type {
            add_text(&mut tantivy_doc, s.content_type, content_type);
        }
        if let Some(ref section) = doc.section {
            add_text(&mut tantivy_doc, s.section, section);
        }

        tantivy_doc
    }
}

fn add_text(doc: &mut TantivyDocument, field: Field, value: &str) {
    doc.add_text(field, value);
}

