//! Uses English stemming tokenizer (`en_stem`) for full-text fields:
//! - SimpleTokenizer → LowerCaser → Stemmer(English)
//!
//! This means "harmonics" matches "harmony", "running" matches "run", etc.

use tantivy::Index;
use tantivy::schema::{
    FAST, Field, STORED, STRING, Schema, SchemaBuilder, TextFieldIndexing, TextOptions,
};
use tantivy::tokenizer::{LowerCaser, SimpleTokenizer, Stemmer, TextAnalyzer};

/// Schema version for cache invalidation.
///
/// Increment this when schema fields change to force index rebuilds.
pub const SCHEMA_VERSION: u32 = 3;

/// Search schema holding field references and the Tantivy schema.
///
/// This struct provides typed access to schema fields, avoiding string lookups
/// during indexing and querying.
#[derive(Clone)]
pub struct SearchSchema {
    schema: Schema,

    // Identity fields
    /// Unique document identifier.
    pub id: Field,
    /// File path for reference.
    pub path: Field,

    // Full-text fields
    /// Document title (boosted 3.0x in search).
    pub title: Field,
    /// Brief description (boosted 2.0x in search).
    pub description: Field,
    /// Main content body (boosted 1.0x in search).
    pub content: Field,

    // Facet fields
    /// Content category for filtering.
    pub category: Field,
    /// Origin/source reference.
    pub source: Field,
    /// Tags for multi-facet filtering.
    pub tags: Field,

    // Metadata fields
    /// Chapter reference.
    pub chapter: Field,
    /// Part/section within source.
    pub part: Field,
    /// Content author.
    pub author: Field,
    /// Publication/creation date.
    pub date: Field,
    /// Type classification (card, chapter, etc.).
    pub content_type: Field,
    /// Specific section reference.
    pub section: Field,
}

impl SearchSchema {
    /// Build the default search schema.
    ///
    /// Creates a 14-field schema suitable for any knowledge domain.
    pub fn build() -> Self {
        let mut builder = SchemaBuilder::new();

        // Text field options with positions (for phrase queries)
        let text_options = TextOptions::default()
            .set_indexing_options(
                TextFieldIndexing::default()
                    .set_tokenizer("en_stem")
                    .set_index_option(tantivy::schema::IndexRecordOption::WithFreqsAndPositions),
            )
            .set_stored();
            .limit(limit);

        // Apply category filter
        if let Some(ref category) = params.category {
            query = query.only_if(format!("category = '{}'", category.replace('\'', "''")));
        }

        // Apply metadata filters
        for (key, value) in &params.metadata_filters {
            query = query.only_if(format!(
                "json_extract(metadata, '$.{}') = '{}'",
                key.replace('\'', "''"),
                value.replace('\'', "''")
            ));
        }

        let results = query
            .execute()
            .await
            .map_err(|e| Error::operation(format!("Vector search failed: {e}")))?;

        let batches: Vec<RecordBatch> = results
            .try_collect()
            .await
            .map_err(|e| Error::operation(format!("Failed to collect results: {e}")))?;

        let mut items = Vec::new();
        for batch in &batches {
            let parsed = parse_search_results(batch)?;
            items.extend(parsed);
        }

        // Filter by threshold and sort
        items.retain(|r| r.score >= threshold);
        items.sort_by(|a, b| {
            b.score
                .partial_cmp(&a.score)
                .unwrap_or(std::cmp::Ordering::Equal)
        });
        items.truncate(limit);

        let total = items.len();
        Ok(VectorSearchResults {
            items,
            total,
            backend: self.name().to_string(),
        })
    }

    fn name(&self) -> &str {
        "lancedb"
    }

    fn document_count(&self) -> Result<usize> {
        Ok(self.document_count)
    }
}

