    // Edge case tests
    // ------------------------------------------------------------------------

    #[test]
    fn test_filter_all_stopwords_fallback() {
        let filter = default_filter();

        // If all words are stopwords, return original
        let original = "the a an";
        assert_eq!(filter.filter(original), original);
    }

