    fn test_filter_empty_query() {
        let filter = default_filter();
        assert_eq!(filter.filter(""), "");
    }

    #[test]
    fn test_filter_single_stopword() {
        let filter = default_filter();
        // Single stopword returns original
        assert_eq!(filter.filter("the"), "the");
    }

