import json,pathlib,tomllib,re
root=pathlib.Path('.')
slice_root=root/'.worktrees/planning/project05-discoverability/arc00-ci-dependencies/slice02-latest-dependencies'
inv=json.loads((slice_root/'artifacts/dependency-inventory.json').read_text())
selected={p['name']:p['selected'] for p in inv['packages']}
manifest_paths=[root/p for p in inv['manifests']]
workspace=tomllib.loads((root/'Cargo.toml').read_text()).get('workspace',{}).get('dependencies',{})
external=set(); bad=[]; internal=[]; decl_count=0
for path in manifest_paths:
    doc=tomllib.loads(path.read_text())
    tables=[]
    if path.name=='Cargo.toml' and path.parent==root:
        tables.append(('workspace.dependencies',doc.get('workspace',{}).get('dependencies',{})))
    for section in ('dependencies','dev-dependencies','build-dependencies'):
        tables.append((section,doc.get(section,{})))
    for section,table in tables:
        for key,val in table.items():
            if isinstance(val,str): val={'version':val}
            if not isinstance(val,dict): continue
            package=val.get('package',key)
            if 'path' in val:
                if val.get('version')"'!='"'0.5.0': internal.append((str(path),section,key,val.get('version')))
                continue
            external.add(package); decl_count+=1
            effective=workspace.get(key,val) if val.get('workspace') else val
            if isinstance(effective,str): effective={'version':effective}
            requirement=effective.get('version') if isinstance(effective,dict) else None
            if package not in selected:
                bad.append((str(path),section,key,'missing inventory'))
            elif requirement"'!=selected[package]:
                bad.append((str(path),section,key,requirement,selected[package]))
print(f'"'manifests={len(manifest_paths)} external_names={len(external)} declaration_sites={decl_count} inventory={len(selected)}')
print(f'internal_version_mismatches={len(internal)} direct_requirement_mismatches={len(bad)} untracked_external={sorted(external-set(selected))} unused_inventory={sorted(set(selected)-external)}')
for row in (internal+bad)[:20]:print(row)
PY"

