//! Avro serialization for Confluent wire format.
//!
//! Converts `serde_json::Map` records to Avro binary with the Confluent
//! wire format header: `[0x00][4-byte schema ID big-endian][avro datum]`.

use apache_avro::Schema;
use apache_avro::types::Value as AvroValue;
use thiserror::Error;

/// Errors during Avro serialization.
#[derive(Debug, Error)]
#[non_exhaustive]
pub enum AvroError {
    /// Schema parsing failed.
    #[error("invalid Avro schema: {0}")]
    InvalidSchema(String),

    /// Value conversion failed.
    #[error("Avro conversion error: {message}")]
    ConversionError {
        /// Error detail.
        message: String,
    },

    /// Avro encoding failed.
    #[error("Avro encoding error: {0}")]
    EncodingError(Box<apache_avro::Error>),
}

/// Serialize a JSON record to Confluent wire format.
///
/// Wire format: `[0x00][schema_id as 4 bytes BE][avro binary datum]`
///
/// # Errors
///
/// Returns `AvroError` if the record cannot be converted to Avro values
/// or if encoding fails.
#[expect(
    deprecated,
    reason = "Keep the established Confluent single-datum encoding while apache-avro 0.23 transitions callers to GenericDatumWriter."
)]
pub fn serialize_record_avro(
    record: &serde_json::Map<String, serde_json::Value>,
    schema: &Schema,
    schema_id: i32,
) -> Result<Vec<u8>, AvroError> {
    // Convert JSON record to Avro Value.
    let avro_value = json_to_avro_record(record, schema)?;

    // Encode to Avro binary datum.
    let datum = apache_avro::to_avro_datum(schema, avro_value)
        .map_err(|e| AvroError::EncodingError(Box::new(e)))?;

    // Build Confluent wire format: magic byte + schema ID + datum.
    let mut buf = Vec::with_capacity(5 + datum.len());
    buf.push(0x00); // Magic byte
    buf.extend_from_slice(&schema_id.to_be_bytes());
    buf.extend_from_slice(&datum);

    Ok(buf)
}

/// Parse an Avro schema from a JSON string.
///
/// # Errors
///
/// Returns `AvroError::InvalidSchema` if parsing fails.
pub fn parse_schema(schema_json: &str) -> Result<Schema, AvroError> {
    Schema::parse_str(schema_json).map_err(|e| AvroError::InvalidSchema(e.to_string()))
}

/// Convert a JSON record to an Avro record value, guided by the schema.
fn json_to_avro_record(
    record: &serde_json::Map<String, serde_json::Value>,
    schema: &Schema,
) -> Result<AvroValue, AvroError> {
    match schema {
        Schema::Record(record_schema) => {
            let mut avro_fields = Vec::new();

            for field in &record_schema.fields {
                let json_val = record.get(&field.name);
                let avro_val = json_value_to_avro(json_val, &field.schema)?;
                avro_fields.push((field.name.clone(), avro_val));
            }

            Ok(AvroValue::Record(avro_fields))
        }
        _ => Err(AvroError::ConversionError {
            message: "top-level schema must be a record".to_string(),
        }),
    }
}

/// Convert a single JSON value to an Avro value based on the target schema.
fn json_value_to_avro(
    value: Option<&serde_json::Value>,
    schema: &Schema,
) -> Result<AvroValue, AvroError> {
    match schema {
        Schema::Null => Ok(AvroValue::Null),
        Schema::Boolean => match value {
            Some(serde_json::Value::Bool(b)) => Ok(AvroValue::Boolean(*b)),
            _ => Ok(AvroValue::Boolean(false)),
        },
        Schema::Int => match value {
            Some(serde_json::Value::Number(n)) => {
                Ok(AvroValue::Int(n.as_i64().unwrap_or(0) as i32))
            }
            Some(serde_json::Value::String(s)) => Ok(AvroValue::Int(s.parse::<i32>().unwrap_or(0))),
            _ => Ok(AvroValue::Int(0)),
        },
        Schema::Long => match value {
            Some(serde_json::Value::Number(n)) => Ok(AvroValue::Long(n.as_i64().unwrap_or(0))),
            Some(serde_json::Value::String(s)) => {
                Ok(AvroValue::Long(s.parse::<i64>().unwrap_or(0)))
            }
            _ => Ok(AvroValue::Long(0)),
        },
        Schema::Float => match value {
            Some(serde_json::Value::Number(n)) => {
                Ok(AvroValue::Float(n.as_f64().unwrap_or(0.0) as f32))
            }
            _ => Ok(AvroValue::Float(0.0)),
        },
        Schema::Double => match value {
            Some(serde_json::Value::Number(n)) => Ok(AvroValue::Double(n.as_f64().unwrap_or(0.0))),
            _ => Ok(AvroValue::Double(0.0)),
        },
        Schema::String => match value {
            Some(serde_json::Value::String(s)) => Ok(AvroValue::String(s.clone())),
            Some(v) => Ok(AvroValue::String(v.to_string())),
            None => Ok(AvroValue::String(String::new())),
        },
        Schema::Union(union_schema) => {
            // Handle ["null", "type"] union (optional fields).
            let variants = union_schema.variants();
            if value.is_none() || matches!(value, Some(serde_json::Value::Null)) {
                // Find null variant.
                for (i, variant) in variants.iter().enumerate() {
                    if *variant == Schema::Null {
                        return Ok(AvroValue::Union(i as u32, Box::new(AvroValue::Null)));
                    }
                }
                return Err(AvroError::ConversionError {
                    message: "union does not contain null".to_string(),
                });
            }
            // Find the first non-null variant that could match.
            for (i, variant) in variants.iter().enumerate() {
                if *variant != Schema::Null {
                    let converted = json_value_to_avro(value, variant)?;
                    return Ok(AvroValue::Union(i as u32, Box::new(converted)));
                }
            }
            Err(AvroError::ConversionError {
                message: "no matching union variant".to_string(),
            })
        }
        _ => {
            // Fallback: serialize as string.
            match value {
                Some(v) => Ok(AvroValue::String(v.to_string())),
                None => Ok(AvroValue::Null),
            }
        }
    }
}

#[cfg(test)]
#[allow(clippy::unwrap_used)]
mod tests {
    use super::*;

    fn test_schema() -> Schema {
        parse_schema(
            r#"{
                "type": "record",
                "name": "Transaction",
                "fields": [
                    {"name": "id", "type": "string"},
                    {"name": "amount", "type": "double"},
                    {"name": "count", "type": "int"},
                    {"name": "active", "type": "boolean"}
                ]
            }"#,
        )
        .unwrap()
    }

    #[test]
    fn test_avro_serialize_simple_record() {
        let schema = test_schema();
        let mut record = serde_json::Map::new();
        record.insert("id".to_string(), serde_json::json!("txn-001"));
        record.insert("amount".to_string(), serde_json::json!(42.50));
        record.insert("count".to_string(), serde_json::json!(3));
        record.insert("active".to_string(), serde_json::json!(true));

        let bytes = serialize_record_avro(&record, &schema, 42).unwrap();
        assert!(!bytes.is_empty());
        // Verify wire format header.
        assert_eq!(bytes[0], 0x00); // Magic byte

        let mut encoded_datum = &bytes[5..];
        let decoded = apache_avro::reader::datum::GenericDatumReader::builder(&schema)
            .build()
            .unwrap()
            .read_value(&mut encoded_datum)
            .unwrap();
        assert_eq!(
            decoded,
            AvroValue::Record(vec![
                ("id".to_string(), AvroValue::String("txn-001".to_string())),
                ("amount".to_string(), AvroValue::Double(42.5)),
                ("count".to_string(), AvroValue::Int(3)),
                ("active".to_string(), AvroValue::Boolean(true)),
            ])
        );
    }

    #[test]
    fn test_avro_serialize_wire_format_header() {
        let schema = test_schema();
        let mut record = serde_json::Map::new();
        record.insert("id".to_string(), serde_json::json!("x"));
        record.insert("amount".to_string(), serde_json::json!(0.0));
        record.insert("count".to_string(), serde_json::json!(0));
        record.insert("active".to_string(), serde_json::json!(false));

        let bytes = serialize_record_avro(&record, &schema, 256).unwrap();

        // Header: [0x00] [schema_id BE 4 bytes]
        assert_eq!(bytes[0], 0x00);
        let schema_id = i32::from_be_bytes([bytes[1], bytes[2], bytes[3], bytes[4]]);
        assert_eq!(schema_id, 256);
    }

    #[test]
    fn test_avro_serialize_with_nullable_fields() {
        let schema = parse_schema(
            r#"{
                "type": "record",
                "name": "OptionalRecord",
                "fields": [
                    {"name": "name", "type": "string"},
                    {"name": "note", "type": ["null", "string"], "default": null}
                ]
            }"#,
        )
        .unwrap();

        let mut record = serde_json::Map::new();
        record.insert("name".to_string(), serde_json::json!("Alice"));
        // note is absent → null

        let bytes = serialize_record_avro(&record, &schema, 1).unwrap();
        assert!(!bytes.is_empty());
    }

//! Server-initiated notification broadcasting.
//!
//! The [`Notifier`] collects `Peer<RoleServer>` handles from connected MCP
//! clients and broadcasts notifications to all of them. Dead peers are
//! automatically pruned on each broadcast.

use std::collections::HashMap;
use std::sync::Arc;

use rmcp::RoleServer;
#[expect(
    deprecated,
    reason = "Preserve the existing MCP logging notification contract for legacy clients."
)]
use rmcp::model::{
    LoggingLevel, LoggingMessageNotificationParam, ResourceUpdatedNotificationParam,
};
use rmcp::service::Peer;
use tokio::sync::RwLock;

/// Broadcasts notifications to all connected MCP clients.
///
/// Each connected client provides a `Peer<RoleServer>` handle via
/// `ServerHandler::on_initialized()`. The `Notifier` stores these handles
/// and broadcasts notifications to all of them, automatically pruning
/// peers that have disconnected.
///
/// `Notifier` is cheaply cloneable (wraps `Arc`) and safe to share across
/// async tasks.
#[derive(Clone)]
pub struct Notifier {
    peers: Arc<RwLock<Vec<Peer<RoleServer>>>>,
    subscriptions: Arc<RwLock<HashMap<String, Vec<Peer<RoleServer>>>>>,
}

impl Notifier {
    /// Create a new `Notifier` with no connected peers.
    pub(crate) fn new() -> Self {
        Self {
            peers: Arc::new(RwLock::new(Vec::new())),
            subscriptions: Arc::new(RwLock::new(HashMap::new())),
        }
    }

    /// Register a newly connected peer.
    pub(crate) async fn add_peer(&self, peer: Peer<RoleServer>) {
        self.peers.write().await.push(peer);
    }

    /// Broadcast a logging notification to all connected clients.
    ///
    /// Returns the number of clients that received the notification
    /// successfully. Dead peers are pruned automatically.
    #[expect(
        deprecated,
        reason = "Preserve the existing MCP logging notification contract for legacy clients."
    )]
    pub async fn log(&self, level: LoggingLevel, logger: &str, data: serde_json::Value) -> usize {
        let param = LoggingMessageNotificationParam::new(level, data).with_logger(logger);
        let mut peers = self.peers.write().await;
        let mut failed = Vec::new();

        for (i, peer) in peers.iter().enumerate() {
            if peer.notify_logging_message(param.clone()).await.is_err() {
                failed.push(i);
            }
        }

        let success = peers.len() - failed.len();
        // Remove dead peers in reverse order to preserve indices
        for i in failed.into_iter().rev() {
            peers.swap_remove(i);
        }
        success
    }

    /// Register a peer's subscription to a resource URI.
    pub async fn subscribe_resource(&self, uri: impl Into<String>, peer: Peer<RoleServer>) {
        self.subscriptions
            .write()
            .await
            .entry(uri.into())
            .or_default()
            .push(peer);
    }

    /// Remove all subscriptions for a resource URI.
    ///
    /// Currently removes all peers subscribed to the URI. Per-peer
    /// removal is not supported because `Peer` does not implement
    /// `PartialEq`.
    pub async fn unsubscribe_resource(&self, uri: &str) {
        self.subscriptions.write().await.remove(uri);
    }

    /// Notify clients that a resource has been updated.
    ///
    /// If any peers have subscribed to the URI, only those peers are
    /// notified. Otherwise, all connected peers are notified (backwards
    /// compatible).
    ///
    /// Returns the number of clients notified successfully.
    pub async fn resource_updated(&self, uri: impl Into<String>) -> usize {
        let uri = uri.into();
        let param = ResourceUpdatedNotificationParam::new(&uri);

        // Check for explicit subscribers first
        let subscriber_peers: Option<Vec<Peer<RoleServer>>> = {
            let subs = self.subscriptions.read().await;
            subs.get(&uri).cloned()
        };

        if let Some(peers) = subscriber_peers {
            let mut success = 0;
            for peer in &peers {
                if peer.notify_resource_updated(param.clone()).await.is_ok() {
                    success += 1;
                }
            }
            // Prune dead subscribers
            if success < peers.len() {
                let mut subs = self.subscriptions.write().await;
                if let Some(sub_peers) = subs.get_mut(&uri) {
                    let mut i = 0;
                    while i < sub_peers.len() {
                        let test_param = ResourceUpdatedNotificationParam::new(&uri);
                        if sub_peers[i]
                            .notify_resource_updated(test_param)
                            .await
                            .is_err()
                        {
                            sub_peers.swap_remove(i);
                        } else {
                            i += 1;
                        }
                    }
                    if sub_peers.is_empty() {
                        subs.remove(&uri);
                    }
                }
            }
            success
        } else {
            // No explicit subscriptions — broadcast to all peers
            let mut peers = self.peers.write().await;
            let mut failed = Vec::new();

            for (i, peer) in peers.iter().enumerate() {
                if peer.notify_resource_updated(param.clone()).await.is_err() {
                    failed.push(i);
                }
            }

            let success = peers.len() - failed.len();
            for i in failed.into_iter().rev() {
                peers.swap_remove(i);
            }
            success
        }
    }

    /// Notify all clients that the resource list has changed.
    ///
    /// Returns the number of clients notified successfully.
    pub async fn resource_list_changed(&self) -> usize {
        let mut peers = self.peers.write().await;
        let mut failed = Vec::new();

        for (i, peer) in peers.iter().enumerate() {
            if peer.notify_resource_list_changed().await.is_err() {
                failed.push(i);
            }
        }

        let success = peers.len() - failed.len();
        for i in failed.into_iter().rev() {
            peers.swap_remove(i);
        }
        success
    }

    /// Return the number of currently connected clients.
    pub async fn client_count(&self) -> usize {
        self.peers.read().await.len()
    }
}

