//! Search backend trait and factory.
//!
//! This module defines the `SearchBackend` trait that all search implementations
//! must satisfy, plus types for search parameters and results.
//!
//! # Backends
//!
//! - `TantivySearch`: Full-text search with Tantivy (requires `fts-tantivy` feature)
//! - `SimpleSearch`: Linear scan fallback for small collections
//!
//! # Example
//!
//! ```rust,ignore
//! use fabryk_fts::{create_search_backend, SearchParams, SearchConfig};
//!
//! let config = SearchConfig::default();
//! let backend = create_search_backend(&config).await?;
//!
//! let params = SearchParams {
//!     query: "functional harmony".to_string(),
//!     limit: Some(10),
//!     ..Default::default()
//! };
//!
//! let results = backend.search(params).await?;
//! println!("Found {} results", results.total);
//! ```

use async_trait::async_trait;
use fabryk_core::Result;
use serde::{Deserialize, Serialize};

use crate::concept_card_extractor::ConceptCardDocumentExtractor;
use crate::document::SearchDocument;
use crate::types::{QueryMode, SearchConfig};

/// Parameters for a search request.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct SearchParams {
    /// Search query string.
    pub query: String,

    /// Maximum results to return.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub limit: Option<usize>,

    /// Filter by category.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub category: Option<String>,

    /// Filter by source.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub source: Option<String>,

    /// Filter by content types (e.g., ["concept", "chapter"]).
    #[serde(skip_serializing_if = "Option::is_none")]
    pub content_types: Option<Vec<String>>,

    /// Query mode override (Smart, And, Or, MinimumMatch).
    #[serde(skip_serializing_if = "Option::is_none")]
    pub query_mode: Option<QueryMode>,

    /// Snippet length in characters.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub snippet_length: Option<usize>,

    /// Domain-specific extra filters passed through from MCP tool arguments.
    /// Search backends can use these for post-filtering or query refinement.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub extra_filters: Option<serde_json::Value>,
}

/// A single search result.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SearchResult {
    /// Unique document identifier.
    pub id: String,

    /// Document title.
    pub title: String,

    /// Brief description or summary.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub description: Option<String>,

    /// Content category.
    pub category: String,

    /// Source reference.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub source: Option<String>,

    /// Search snippet with query context.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub snippet: Option<String>,

    /// Relevance score (0.0 to 1.0+, higher is better).
    pub relevance: f32,

    /// Content type classification.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub content_type: Option<String>,

    /// File path (for debugging/reference).
    #[serde(skip_serializing_if = "Option::is_none")]
    pub path: Option<String>,

    /// Chapter reference.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub chapter: Option<String>,

    /// Section reference.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub section: Option<String>,
}

/// Collection of search results.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SearchResults {
    /// Search result items.
    pub items: Vec<SearchResult>,

    /// Total number of matching documents (may be > items.len() if limited).
    pub total: usize,

    /// Backend that executed the search.
    pub backend: String,
}

impl SearchResults {
    /// Create empty results.
    pub fn empty(backend: &str) -> Self {
        Self {
            items: Vec::new(),
            total: 0,
            backend: backend.to_string(),
        }
    }
}

/// Abstract search backend trait.
///
/// Implementations provide different search strategies:
/// - `TantivySearch`: Full-text search with BM25 scoring, stemming, fuzzy matching
/// - `SimpleSearch`: Linear scan with substring matching (fallback)
///
/// # Async
///
/// The `search` method is async to support I/O-bound operations (file reading,
/// index access) without blocking.
#[async_trait]
pub trait SearchBackend: Send + Sync {
    /// Execute a search query.
    ///
    /// Returns results ordered by relevance (highest first).
    async fn search(&self, params: SearchParams) -> Result<SearchResults>;

    /// Get the backend name for diagnostics.
    fn name(&self) -> &str;

    /// Check if the backend is ready to handle queries.
    fn is_ready(&self) -> bool {
        true
    }
}

/// Create a search backend based on configuration.
///
/// Selection logic:
/// 1. If `fts-tantivy` feature enabled and index exists → `TantivySearch`
/// 2. Otherwise → `SimpleSearch` (linear scan fallback)
///
/// # Errors
///
/// Returns an error if the configured backend cannot be initialized.
pub async fn create_search_backend(config: &SearchConfig) -> Result<Box<dyn SearchBackend>> {
    match config.backend.as_str() {
        #[cfg(feature = "fts-tantivy")]
        "tantivy" => {
            if let Some(ref index_path) = config.index_path {
                let path = std::path::Path::new(index_path);
                if path.exists() {
                    match crate::tantivy_search::TantivySearch::new(config) {
                        Ok(backend) => return Ok(Box::new(backend)),
                        Err(e) => {
                            log::warn!(
                                "Failed to open Tantivy index: {e}, falling back to simple search"
                            );
                        }
                    }
                }
            }
            // Fall through to simple search
            Ok(Box::new(SimpleSearch::with_default_extractor(config)))
        }
        _ => Ok(Box::new(SimpleSearch::with_default_extractor(config))),
    }
}

/// Trait for extracting [`SearchDocument`]s from file content.
///
/// This is the non-feature-gated version of document extraction, usable by
/// [`SimpleSearch`] without requiring the `fts-tantivy` feature.
///
/// # Example
///
/// ```rust,ignore
/// struct MyExtractor;
///
/// impl SimpleDocumentExtractor for MyExtractor {
///     fn extract(&self, path: &std::path::Path, content: &str) -> Option<SearchDocument> {
///         Some(SearchDocument::builder()
///             .id("doc")
///             .title("Title")
///             .content(content)
///             .category("general")
///             .build())
///     }
/// }
/// ```
//! Full-text search backend using Tantivy.
//!
//! This module provides `TantivySearch`, the primary search backend for
//! production use. It executes queries against a Tantivy index with:
//! - BM25 scoring
//! - Multi-field weighted search
//! - Category/source/content_type filtering
//! - Snippet generation
//!
//! # Usage
//!
//! ```rust,ignore
//! use fabryk_fts::{TantivySearch, SearchConfig, SearchParams};
//!
//! let config = SearchConfig {
//!     index_path: Some("/path/to/index".to_string()),
//!     ..Default::default()
//! };
//!
//! let backend = TantivySearch::new(&config)?;
//! let results = backend.search(SearchParams {
//!     query: "functional harmony".to_string(),
//!     limit: Some(10),
//!     ..Default::default()
//! }).await?;
//! ```

use std::path::Path;

use async_trait::async_trait;
use fabryk_core::{Error, Result};
use tantivy::collector::TopDocs;
use tantivy::query::Query;
use tantivy::{Index, IndexReader, ReloadPolicy};

use tantivy::schema::Value;

use crate::backend::{SearchBackend, SearchParams, SearchResult, SearchResults};
use crate::query::QueryBuilder;
use crate::schema::SearchSchema;
use crate::types::SearchConfig;

/// Tantivy-based full-text search backend.
pub struct TantivySearch {
    /// Retained for ownership — dropping the Index would invalidate the reader.
    #[allow(dead_code)]
    index: Index,
    reader: IndexReader,
    schema: SearchSchema,
    config: SearchConfig,
}

impl TantivySearch {
    /// Create a new Tantivy search backend.
    ///
    /// Opens an existing index at the configured path.
    pub fn new(config: &SearchConfig) -> Result<Self> {
        let index_path = config
            .index_path
            .as_ref()
            .ok_or_else(|| Error::config("index_path is required for TantivySearch"))?;

        let path = Path::new(index_path);
        if !path.exists() {
            return Err(Error::not_found("Index", index_path));
        }

        let index = Index::open_in_dir(path)
            .map_err(|e| Error::operation(format!("Failed to open index: {e}")))?;

        let schema = SearchSchema::build();
        SearchSchema::register_tokenizers(&index);

        let reader = index
            .reader_builder()
            .reload_policy(ReloadPolicy::OnCommitWithDelay)
            .try_into()
            .map_err(|e| Error::operation(format!("Failed to create reader: {e}")))?;

        Ok(Self {
            index,
            reader,
            schema,
            config: config.clone(),
        })
    }

    /// Execute a query and return scored document addresses.
    fn execute_query(
        &self,
        query: &dyn Query,
        limit: usize,
    ) -> Result<Vec<(f32, tantivy::DocAddress)>> {
        let searcher = self.reader.searcher();
        let top_docs = searcher
            .search(query, &TopDocs::with_limit(limit).order_by_score())
            .map_err(|e| Error::operation(format!("Search failed: {e}")))?;

        Ok(top_docs)
    }

    /// Convert Tantivy documents to SearchResults.
    fn convert_results(
        &self,
        docs: Vec<(f32, tantivy::DocAddress)>,
        query_str: &str,
    ) -> Result<Vec<SearchResult>> {
        let searcher = self.reader.searcher();
        let mut results = Vec::with_capacity(docs.len());

        for (score, doc_address) in docs {
            let doc: tantivy::TantivyDocument = searcher
                .doc(doc_address)
                .map_err(|e| Error::operation(format!("Failed to retrieve document: {e}")))?;

            let id = get_text_field(&doc, self.schema.id).unwrap_or_default();
            let title = get_text_field(&doc, self.schema.title).unwrap_or_default();
            let description = get_text_field(&doc, self.schema.description);
            let content = get_text_field(&doc, self.schema.content).unwrap_or_default();
            let category = get_text_field(&doc, self.schema.category).unwrap_or_default();
            let source = get_text_field(&doc, self.schema.source);
            let path = get_text_field(&doc, self.schema.path);
            let content_type = get_text_field(&doc, self.schema.content_type);
            let chapter = get_text_field(&doc, self.schema.chapter);
            let section = get_text_field(&doc, self.schema.section);

            // Generate snippet
            let snippet = self.generate_snippet(query_str, &description, &content);

            results.push(SearchResult {
                id,
                title,
                description,
                category,
                source,
                snippet,
                relevance: score,
                content_type,
                path,
                chapter,
                section,
            });
        }

        Ok(results)
    }

    /// Generate a search snippet from description or content.
    fn generate_snippet(
        &self,
        query: &str,
        description: &Option<String>,
        content: &str,
    ) -> Option<String> {
        let max_len = self.config.snippet_length;

        // Try description first
        if let Some(desc) = &description
            && let Some(snippet) = find_snippet_in_text(desc, query, max_len)
        {
            return Some(snippet);
        }

        // Try content
        if let Some(snippet) = find_snippet_in_text(content, query, max_len) {
            return Some(snippet);
        }

        // Fallback to description or content start
        description.clone().or_else(|| {
            if content.len() > max_len {
                let trunc = content.floor_char_boundary(max_len);
                Some(format!("{}...", &content[..trunc]))
            } else if !content.is_empty() {
                Some(content.to_string())
            } else {
                None
            }
        })
    }
}

