    fn make_test_documents(dimension: usize) -> Vec<EmbeddedDocument> {
        vec![
            EmbeddedDocument::new(
                VectorDocument::new("doc-1", "harmony concepts")
                    .with_category("harmony")
                    .with_metadata("tier", "beginner"),
