        .await?;
    let table = database.open_table("cc_vectors").execute().await?;
    let schema = table.schema().await?;
    assert_eq!(schema.fields().iter().map(|field| field.name().as_str()).collect::<Vec<_>>(),
        ["id", "text", "category", "metadata", "vector"]);
    assert_eq!(schema.field_with_name("id")?.data_type(), &DataType::Utf8);
    assert!(!schema.field_with_name("id")?.is_nullable());
    assert_eq!(schema.field_with_name("text")?.data_type(), &DataType::Utf8);
    assert!(!schema.field_with_name("text")?.is_nullable());
    assert_eq!(schema.field_with_name("category")?.data_type(), &DataType::Utf8);
    assert!(schema.field_with_name("category")?.is_nullable());
    assert_eq!(schema.field_with_name("metadata")?.data_type(), &DataType::Utf8);
    assert!(!schema.field_with_name("metadata")?.is_nullable());
    match schema.field_with_name("vector")?.data_type() {
        DataType::FixedSizeList(item, 4) => {
            assert_eq!(item.name(), "item");
            assert_eq!(item.data_type(), &DataType::Float32);
            assert!(item.is_nullable());
        }
        other => panic!("unexpected vector schema: {other:?}"),
    }
    assert!(!schema.field_with_name("vector")?.is_nullable());

    let batches = table.query().execute().await?.try_collect::<Vec<_>>().await?;
    let mut observed = HashMap::new();
    let mut total_rows = 0;
    for batch in &batches {
        let ids = batch.column_by_name("id").unwrap().as_any().downcast_ref::<StringArray>().unwrap();
        let texts = batch.column_by_name("text").unwrap().as_any().downcast_ref::<StringArray>().unwrap();
        let categories = batch.column_by_name("category").unwrap().as_any().downcast_ref::<StringArray>().unwrap();
        let metadata = batch.column_by_name("metadata").unwrap().as_any().downcast_ref::<StringArray>().unwrap();
        let vectors = batch.column_by_name("vector").unwrap().as_any().downcast_ref::<FixedSizeListArray>().unwrap();
        for row in 0..batch.num_rows() {
            total_rows += 1;
            let vector_values = vectors.value(row);
            let vector = vector_values.as_any().downcast_ref::<Float32Array>().unwrap();
            let metadata: HashMap<String, String> = serde_json::from_str(metadata.value(row))?;
            assert!(observed.insert(
                ids.value(row).to_string(),
                (
                    texts.value(row).to_string(),
                    (!categories.is_null(row)).then(|| categories.value(row).to_string()),
                    metadata,
                    vector.values().to_vec(),
                ),
            ).is_none(), "duplicate old row id {}", ids.value(row));
        }
    }
    assert_eq!(total_rows, 3, "the old table contains exactly three rows");
    assert_eq!(observed.len(), 3);
    assert_eq!(observed["doc-null"], ("Document with nullable category".into(), None, HashMap::from([("owner".into(), "acme".into())]), vec![0.0; 4]));
    assert_eq!(observed["doc-one"], ("One vector row".into(), Some("reports".into()), HashMap::from([("owner".into(), "acme".into())]), vec![1.0; 4]));
    assert_eq!(observed["doc-two"], ("Two vector row".into(), Some("archive".into()), HashMap::from([("owner".into(), "example".into())]), vec![2.0; 4]));
    drop(table);
    drop(database);

    let metadata_path = root.join("index_metadata.json");
    let metadata = load_metadata(&metadata_path)?;
    assert_eq!(serde_json::to_value(&metadata)?, serde_json::json!({
        "content_hash": "golden-lance-content-hash-42",
        "document_count": 3,
        "embedding_dimension": 4,
        "built_at": "2026-03-13T10:00:00Z",
        "provider": "cc-zero-oracle",
        "model": "fixed-4d-fixture-v1"
    }));
    assert_eq!(metadata.content_hash, "golden-lance-content-hash-42");
    assert_eq!(metadata.document_count, 3);
    assert_eq!(metadata.embedding_dimension, 4);
    assert_eq!(metadata.built_at, "2026-03-13T10:00:00Z");
    assert_eq!(metadata.provider, "cc-zero-oracle");
    assert_eq!(metadata.model, "fixed-4d-fixture-v1");
    assert!(is_index_fresh(&metadata_path, "golden-lance-content-hash-42"));
    assert!(!is_index_fresh(&metadata_path, "different-independent-hash"));

    println!("upgraded Lance SDK read three golden rows and schema; product metadata reader and freshness check passed");
    Ok(())
}
use async_trait::async_trait;
use fabryk_core::Result as FabrykResult;
use fabryk_vector::{
    EmbeddedDocument, EmbeddingProvider, LancedbBackend, VectorBackend, VectorDocument,
    VectorSearchParams,
};
use futures::TryStreamExt;
use lancedb::query::ExecutableQuery;
use std::path::PathBuf;
use std::sync::Arc;

struct ZeroProvider;

#[async_trait]
impl EmbeddingProvider for ZeroProvider {
    async fn embed(&self, _text: &str) -> FabrykResult<Vec<f32>> {
        Ok(vec![0.0; 4])
    }

    fn dimension(&self) -> usize { 4 }
    fn name(&self) -> &str { "cc-zero-oracle" }
}

fn documents() -> Vec<EmbeddedDocument> {
    let mut nullable = VectorDocument::new("doc-null", "Document with nullable category")
        .with_metadata("owner", "acme");
    nullable.category = None;
    vec![
        EmbeddedDocument::new(nullable, vec![0.0; 4]),
        EmbeddedDocument::new(
            VectorDocument::new("doc-one", "One vector row")
                .with_category("reports")
                .with_metadata("owner", "acme"),
            vec![1.0; 4],
        ),
        EmbeddedDocument::new(
            VectorDocument::new("doc-two", "Two vector row")
                .with_category("archive")
                .with_metadata("owner", "example"),
            vec![2.0; 4],
        ),
    ]
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let root = PathBuf::from(std::env::args().nth(1).ok_or("separate copied fixture directory required")?);
    let database_path = root.join("lance-db");
    let uri = database_path.to_str().ok_or("UTF-8 database path")?;

    let connection = lancedb::connect(uri).execute().await?;
    let unrelated_schema = Arc::new(arrow_schema::Schema::new(vec![
        arrow_schema::Field::new("marker", arrow_schema::DataType::Utf8, false),
    ]));
    connection.create_empty_table("unrelated", unrelated_schema).execute().await?;
    drop(connection);

    let backend = LancedbBackend::build(
        uri,
        "cc_vectors",
        Arc::new(ZeroProvider),
        documents(),
    )
    .await?;
    let results = backend
        .search(VectorSearchParams::new("known zero query").with_limit(10))
        .await?;
    assert_eq!(results.items.iter().map(|item| item.id.as_str()).collect::<Vec<_>>(),
        ["doc-null", "doc-one", "doc-two"]);
    for ((item, distance), score) in results.items.iter()
        .zip([0.0_f32, 4.0, 16.0])
        .zip([1.0_f32, 1.0 / 5.0, 1.0 / 17.0])
    {
        assert!((item.distance - distance).abs() < 1e-5);
        assert!((item.score - score).abs() < 1e-5);
    }

    let category = backend.search(
        VectorSearchParams::new("known zero query").with_category("reports")
    ).await?;
    assert_eq!(category.items.len(), 1);
    assert_eq!(category.items[0].id, "doc-one");

    let threshold = backend.search(
        VectorSearchParams::new("known zero query").with_threshold(0.5)
    ).await?;
    assert_eq!(threshold.items.iter().map(|item| item.id.as_str()).collect::<Vec<_>>(), ["doc-null"]);

    let metadata = backend.search(
        VectorSearchParams::new("known zero query").with_filter("owner", "acme")
    ).await?;
    assert_eq!(metadata.items.len(), 2);
    assert!(metadata.items.iter().all(|item| item.metadata["owner"] == "acme"));

    let farther_only = backend.search(
        VectorSearchParams::new("known zero query")
            .with_filter("owner", "example")
            .with_limit(1),
    ).await?;
    assert_eq!(farther_only.items.len(), 1);
    assert_eq!(farther_only.items[0].id, "doc-two");
    assert!((farther_only.items[0].distance - 16.0).abs() < 1e-5);
    assert!((farther_only.items[0].score - 1.0 / 17.0).abs() < 1e-5);
    let conjunction = backend.search(
        VectorSearchParams::new("known zero query")
            .with_category("archive")
            .with_filter("owner", "example"),
    ).await?;
    assert_eq!(conjunction.items.iter().map(|item| item.id.as_str()).collect::<Vec<_>>(), ["doc-two"]);
    let absent = backend.search(
        VectorSearchParams::new("known zero query").with_filter("missing-key", "value"),
    ).await?;
    assert!(absent.items.is_empty());

    drop(backend);
    let connection = lancedb::connect(uri).execute().await?;
    let tables = connection.table_names().execute().await?;
    assert!(tables.iter().any(|table| table == "cc_vectors"));
    assert!(tables.iter().any(|table| table == "unrelated"));

    // Ensure LanceDB can still query the rebuilt table through its public SDK.
    let table = connection.open_table("cc_vectors").execute().await?;
    let batches = table.query().execute().await?.try_collect::<Vec<_>>().await?;
    assert_eq!(batches.iter().map(|batch| batch.num_rows()).sum::<usize>(), 3);
    println!("product rebuild/query returned oracle distances and preserved the unrelated table on an old-fixture copy");
    Ok(())
}

use fabryk_fts::{SearchConfig, StopwordFilter};
use std::path::PathBuf;

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let oracle_path = PathBuf::from(std::env::args().nth(1).ok_or("baseline stop-words 0.10.0 ISO JSON path required")?);
    let source: serde_json::Value = serde_json::from_slice(&std::fs::read(oracle_path)?)?;
    let english = source["en"].as_array().ok_or("baseline ISO English array missing")?;
    assert_eq!(english.len(), 1298);
    let filter = StopwordFilter::new(&SearchConfig::default());
    for entry in english {
        let word = entry.as_str().ok_or("baseline ISO entry is not a string")?;
        assert!(filter.is_stopword(word), "product API omitted baseline ISO word {word}");
    }
    for word in ["able", "across", "therefore", "system"] {
        assert!(filter.is_stopword(word), "ISO-only control {word}");
    }
    for word in ["ain", "hadn", "mightn", "mustn", "needn", "shan"] {
        assert!(!filter.is_stopword(word), "NLTK-only control {word}");
    }
    println!("product StopwordFilter matched all 1298 baseline stop-words 0.10.0 ISO English entries and six NLTK-only exclusions");
    Ok(())
}
